}

#[test]
fn fifo_send_rules_and_deduplication_window() {
    script(&[
        (CREATE_F, ok()),
        (
            r#"{"Command":"SendMessage","QueueName":"f.fifo","Body":"a","GroupId":"g","DeduplicationId":"d","DelaySeconds":0}"#,
